def count_words(text):
    return len(text.split())


def wrap(text, width):
    lines = []
    cur = ""
    for w in text.split():
        # When cur is empty initially, we don't need extra space for the first word
        if cur == "":
            cur = w
        else:
            extra = len(w) + 1
            if len(cur) + extra > width - 1:
                lines.append(cur)
                cur = w
            else:
                cur = f"{cur} {w}"
    if cur:
        lines.append(cur)
    return lines

